<template>
    <div>
      <!-- Usamos la clase "d-flex" para flexbox y "flex-column" para apilar los botones verticalmente -->
      <div class="d-flex flex-column">
        <v-btn :text="true" @click="scrollToSection('app')" :class="{ 'selected': selectedSection === 'app' }"><span class="small-text font-weight-bold">Problem</span></v-btn>
        <v-btn :text="true" @click="scrollToSection('2-Building or Neighborhood')" :class="{ 'selected': selectedSection === '2-Building or Neighborhood' }"><span class="small-text font-weight-bold">Scenarios</span></v-btn>
        <v-btn :text="true" @click="scrollToSection('1-Decision Purpose')" :class="{ 'selected': selectedSection === '1-Decision Purpose' }"><span class="small-text font-weight-bold">Accepted Model Risk</span></v-btn>
        <v-btn :text="true" @click="scrollToSection('3-Design Space')" :class="{ 'selected': selectedSection === '3-Design Space' }"><span class="small-text font-weight-bold">Test Requirements</span></v-btn>
        <v-btn :text="true" @click="scrollToSection('4-Simulation Requirements')" :class="{ 'selected': selectedSection === '4-Simulation Requirements' }"><span class="small-text font-weight-bold">Modeling and Verification</span></v-btn>
        
        <v-btn :text="true" @click="scrollToSection('6-Simulation Tools')" :class="{ 'selected': selectedSection === '6-Simulation Tools' }"><span class="small-text font-weight-bold">Simulation Tools</span></v-btn>
        
      </div>
    </div>
  </template>
  
  <script>
  export default {
    name: 'NavigationBar',
    data() {
      return {
        selectedSection: '' // Variable para almacenar la sección seleccionada
      };
    },
    methods: {
      scrollToSection(sectionId) {
        const section = document.getElementById(sectionId);
        if (section) {
          if (sectionId === 'app') {
            window.scrollTo({ top: 0, behavior: 'smooth' });
          } else {
            section.scrollIntoView({ behavior: 'smooth' });
          }
          this.selectedSection = sectionId; // Actualiza la sección seleccionada
        }
      }
    }
  };
  </script>
  
  <style scoped>
  /* Estilos específicos de la barra de navegación */
  /* Puedes agregar estilos adicionales aquí para personalizar la apariencia de los botones */
  /* Por ejemplo, puedes cambiar el color de fondo o el tamaño de fuente */
  
  .small-text {
    font-size: 10px; /* Tamaño de fuente más pequeño */
  }
  
  .font-weight-bold {
    font-weight: bold; /* Texto en negrita */
  }
  
  .selected {
    background-color:rgb(44, 182, 125); /* Color de fondo verde cuando el botón está seleccionado */
    color: white; /* Texto blanco cuando el botón está seleccionado */
  }
  </style>
  