<template>
  <v-app>
    <v-container fluid>
      <div id="header" class="header">
        <HelloWorld />
      </div>
      <v-row>
        <!-- Barra de navegación a la izquierda -->
        <v-col cols="2">
          <div id="Navigation" class="nav-container" v-if="selectedProblem">
            <NavigationBar />
            <v-container id="6-Simulation Tools" class="button-container">
              <v-btn @click="goToAbout" class="interactive-button">Problem Solving</v-btn>
            </v-container>
          </div>
        </v-col>
        <!-- Contenido principal -->
        <v-col cols="10">
          <HomePage :selectedLab="selectedLab" @selectedProblem="onProblemSelected" @selectedLivingLab="onSelectedLivingLab"/>

          <!-- Sección condicional que solo se muestra si se ha seleccionado un problema -->
          <template v-if="selectedProblem">
            <div class="decision-purpose-container">
              <v-card id="1-Decision Purpose" class="section-card" text-color="primary" elevation="2">
                <v-card-title class="title">Location</v-card-title>
                <LivingLabSelection :selectedProblem="selectedProblem" @selectedLab="onLabSelected"/>
              </v-card>
              <FirstMap :selectedLab="selectedLivingLab" class="first-map"/>
            </div>

            <v-card id="2-Building or Neighborhood" class="section-card" text-color="primary" elevation="2">
              <v-card-title class="title">Problem and decision</v-card-title>
              <NeedBox :selectedProblem="selectedProblem"/>
            </v-card>

            <v-card id="3-Design Space" class="section-card" text-color="primary" elevation="2">
              <v-card-title class="title">Buildings and infrastructure considered</v-card-title>
              <AutomaticBuilding :selectedLab="selectedLivingLab" :selectedProblem="selectedProblem"/>
              <Visual3D />
            </v-card>

            <v-card id="4-Simulation Requirements" class="section-card" text-color="primary" elevation="2">
              <v-card-title class="title">Stakeholders</v-card-title>
              <AutomaticStakeForm :selectedLab="selectedLivingLab" :selectedProblem="selectedProblem"/>
            </v-card>

            <v-card id="5-Modeling Choice" class="section-card" text-color="primary" elevation="2">
              <v-card-title class="title">KPIs</v-card-title>
              <AutomaticKpiForm :selectedLab="selectedLivingLab" :selectedProblem="selectedProblem"/>
            </v-card>


          </template>
        </v-col>
      </v-row>
    </v-container>
  </v-app>
</template>

<script>
import { defineComponent } from 'vue';
import '@mdi/font/css/materialdesignicons.css';
import HelloWorld from '/src/components/HelloWorld.vue';
import NavigationBar from '/src/components/NavigationBar.vue';
import HomePage from '/src/components/HomePage.vue';
import LivingLabSelection from '/src/components/LivingLabSelection.vue';
import AutomaticKpiForm from '/src/components/AutomaticKpiForm.vue';
import AutomaticStakeForm from '/src/components/AutomaticStakeForm.vue';
import AutomaticBuilding from '/src/components/AutomaticBuilding.vue';
import NeedBox from '/src/components/NeedBox.vue';
import FirstMap from '/src/components/FirstMap.vue';
import Visual3D from '/src/components/Visual3D.vue';

export default defineComponent({
  components: {
    NavigationBar,
    HomePage,
    LivingLabSelection,
    HelloWorld,
    AutomaticKpiForm,
    AutomaticStakeForm,
    AutomaticBuilding,
    NeedBox,
    FirstMap,
    Visual3D,
  },
  data() {
    return {
      selectedLab: '',
      selectedProblem: '',
      selectedLivingLab: '', // Variable para almacenar el ID del problema seleccionado
    };
  },
  methods: {
    // Método para manejar el evento emitido desde HomePage.vue
    onProblemSelected(selectedProblem) {
      this.selectedProblem = selectedProblem;
    },
    // Método para manejar el evento emitido desde LivingLabSelection.vue
    onLabSelected(selectedLab) {
      this.selectedLab = selectedLab;
    },
    onSelectedLivingLab(selectedLivingLab) {
      this.selectedLivingLab = selectedLivingLab;
    },
    goToAbout() {
      this.$router.push({
        name: 'AboutPage',
        query: {
          selectedLab: this.selectedLivingLab,
          selectedProblem: this.selectedProblem,
        },
      }).then(() => {
        // Desplazarse al top de la página
        window.scrollTo(0, 0);
      });
    },
  },
  watch: {
    selectedProblem(newValue) {
      // Realiza cualquier acción necesaria cuando selectedProblem cambia
      console.log('selectedProblem ha cambiado a:', newValue);
    },
  },
});
</script>

<style>
#app {
  font-family: Avenir, Helvetica, Arial, sans-serif;
  text-align: center;
}
.nav-container {
  top: 0;
  position: sticky;
  z-index: 1000;
  background-color: white;
}

.decision-purpose-container {
  display: flex;
  align-items: flex-start; /* Alinea los elementos al inicio verticalmente */
  margin-bottom: 20px; /* Espacio entre la fila y el resto del contenido */
}

.first-map {
  margin-left: 20px; /* Espacio entre el componente de mapa y el contenedor de decisiones */
}

/* Estilos para las tarjetas de sección */
.section-card {
  margin-bottom: 20px; /* Espacio entre tarjetas */
}

.title {
  text-align: left; /* Alineación del texto a la izquierda */
  font-size: 18px; /* Tamaño del texto */
  font-weight: bold; /* Texto en negrita */
  color: rgb(251, 252, 250); /* Color del texto */
  background-color: rgb(44, 182, 125);
}
#button-container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 10vh;
  font-size: 15px;
  font-style: bold;
}

#interactive-button {
  font-size: 10px;
  font-style: bold;
  padding: 10px 20px;
  background-color: #2196F3;
  color: white;
  border-radius: 10px;
  transition: all 0.3s ease;
}

.interactive-button:hover {
  background-color: rgb(44, 182, 125);
  transform: translateY(-2px);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
}

.interactive-button:active {
  background-color: rgb(44, 182, 125);
  transform: translateY(1px);
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
}
  /* Estilo específico para el botón "Problem Solving" */
#Navigation .button-container .interactive-button {
    font-size: small; /* Texto en negrita */
    padding: 10px 15px; /* Aumentar el tamaño del botón */
    width: 100%;
  }
</style>

